<br />
<br />                        if (hoeDirtAtTile2 == null)
<br />                        {
<br />                            if (FruitTree.IsTooCloseToAnotherTree(tile, l, !IsFruitTreeSapling()))
<br />                            {
<br />                                if (showError)
<br />                                {
