<br />While the "placementAction" for fruit trees follow this here.
<br />[code]        if (isSapling())
<br />        {
<br />            if (IsWildTreeSapling() || IsFruitTreeSapling())
<br />            {
<br />                if (FruitTree.IsTooCloseToAnotherTree(new Vector2(x / 64, y / 64), location))
<br />                {
