<br />            string text3 = location.doesTileHaveProperty((int)vector.X, (int)vector.Y, "Type", "Back");
<br />            bool flag2 = location.doesEitherTileOrTileIndexPropertyEqual((int)vector.X, (int)vector.Y, "CanPlantTrees", "Back", "T");
<br />            if ((location is Farm &amp;&amp; (flag || text3 == "Grass" || text3 == "Dirt" || flag2) &amp;&amp; (!location.IsNoSpawnTile(vector, "Tree") || flag2)) || ((flag || text3 == "Stone") &amp;&amp; location.CanPlantTreesHere(base.ItemId, (int)vector.X, (int)vector.Y, out deniedMessage2)))
<br />            {
<br />                location.playSound("dirtyHit");
<br />                DelayedAction.playSoundAfterDelay("coin", 100);
<br />                if (IsTeaSapling())
