<br />                };
<br />                fruitTree.growthRate.Value = Math.Max(1, base.Quality + 1);
<br />                location.terrainFeatures.Add(vector, fruitTree);
<br />                return true;
<br />            }
<br />
<br />            if (deniedMessage2 == null)
<br />            {
<br />                deniedMessage2 = Game1.content.LoadString("Strings&#92;&#92;StringsFromCSFiles:Object.cs.13068");
<br />            }
<br />
<br />            Game1.showRedMessage(deniedMessage2);
<br />            return false;
<br />        }[/code]
<br />
<br />Do you see the disconnect? 
<br />
<br />While the "placementAction" is hardcoded to the farm, while "canBePlaced" isn't. So even if a map has the map property of "ForceAllowTreePlanting", it's completely ignored if the map isn't the farm due to how the "placementAction" is coded. 
<br />
<br />So a quick harmony prefix, changes the "placementAction" to follow the "canBePlaced" rules. This patch isn't extensively tested, so you might be able to plant fruit trees in many more places than intended. 
